import re, json

def parse(path):
    rows = []
    pat = re.compile(r"(?:critic-)?step (\d+): (\{.*\})")
    for line in open(path, errors="replace"):
        m = pat.search(line)
        if m:
            try:
                d = eval(m.group(2), {"nan": float("nan"), "inf": float("inf")})
            except Exception:
                continue
            rows.append((m.group(1), d))
    return rows

def get(d, k, default=None):
    for full in (f"train/{k}", k):
        if full in d: return d[full]
    return default

for name, path in [("STAGE A", "stage_a.log"), ("STAGE B", "stage_b.log")]:
    rows = parse(path)
    actors = [(s,d) for s,d in rows if all(f"train/{k}" in d for k in ("pg_loss","entropy_loss"))] 
    print(f"===== {name}: {len(rows)} step lines, {len(actors)} actor step lines =====")
    print(f"{'step':>5} {'pg_loss':>9} {'clipfrac':>9} {'kl':>9} {'absdiff':>9} {'gradn':>8} {'entropy':>8} {'lr':>9} {'rew':>7} {'resp':>6}")
    for s, d in actors:
        def g(k):
            v = get(d,k)
            if isinstance(v,float): return f"{v:.5g}"
            return str(v)
        print(f"{s:>5} {g('pg_loss'):>9} {g('pg_clipfrac'):>9} {g('ppo_kl'):>9} {g('rollout_logprob_abs_diff'):>9} {g('grad_norm'):>8} {g('entropy_loss'):>8} {g('lr-pg_0/1') if get(d,'lr-pg_0/1') is not None else g('lr-pg'):>9} {g('reward') or '-':>7} {g('response_length') or '-':>6}")
