arguments.command:
cd /tmp/etanalysis && python3 - <<'EOF'
import re, json
ansi = re.compile(r'\x1b\[[0-9;]*m')
rows = {}
for line in open('clean_b.log', errors='ignore'):
    line = ansi.sub('', line)
    m = re.match(r".*\[2026-10-09 (\d\d:\d\d:\d\d)\].*? - (rollout (\d+): (\{.*\})|passrate (\d+): (\{.*\}))\s*$", line)
    if m:
        t = m.group(1)
        if m.group(3):
            rows.setdefault(('rollout', int(m.group(3))), (t, m.group(4)))
        else:
            rows.setdefault(('passrate', int(m.group(5))), (t, m.group(6)))
def fmt(d):
    try: d = json.loads(d)
    except Exception: return d
    return {k: (round(v,4) if isinstance(v,(int,float)) else v) for k,v in d.items()}
for key in sorted(rows, key=lambda k: (rows[k][0], k)):
    t, d = rows[key]
    print(t, key[0], key[1], fmt(d))
EOF

